style.css:
/* Cambiar el logo de Google por tu logo de Viajexmundo */
img[src*="logo"] {
  content: url("https://i.imgur.com/zpktZjY.png") !important;
  width: 150px !important;
  height: auto !important;
  object-fit: contain;
}

/* Ocultar el logo original si aparece detrás */
img[src*="logo"] {
  visibility: hidden !important;
}

/* Crear un nuevo logo encima */
header::after {
  content: url("https://i.imgur.com/zpktZjY.png");
  display: block;
  width: 150px;
  height: auto;
  position: absolute;
  top: 10px;
  left: 20px;
  z-index: 1000;
}
